template <int kN>
__global__ void finalize_panel_tridiagonal(
    const float* __restrict__ matrix, float* __restrict__ diagonal,
    float* __restrict__ off_diagonal, float* __restrict__ taus) {
  constexpr int n = kN;
  const int matrix_index = static_cast<int>(blockIdx.x);
  const int64_t matrix_offset = static_cast<int64_t>(matrix_index) * n * n;
  const int64_t vector_offset = static_cast<int64_t>(matrix_index) * n;
