}

template <int kEigenpairsPerBlock, int kGroupWidth, int kVectorPitch,
          int kBisectionIterations, bool kColumnMajorReflectors,
          bool kBacktransform>
__global__ void tridiagonal_eigh_and_backtransform(
    const float* reflectors, const float* input_diagonal,
    const float* input_off_diagonal, const float* taus, float* vectors,
    float* values, int* info, int n) {
  constexpr int kThreads = 128;
  extern __shared__ float shared[];
  float* d = shared;
  float* e = d + n;
  float* tile_vectors = e + n;
  float* tile_factors = tile_vectors + n * kVectorPitch;
  __shared__ float lower_bounds[kThreads];
  __shared__ float upper_bounds[kThreads];

  const int tid = static_cast<int>(threadIdx.x);
  const int tiles_per_matrix = (n + kEigenpairsPerBlock - 1) /
      kEigenpairsPerBlock;
  const int matrix = static_cast<int>(blockIdx.x) / tiles_per_matrix;
  const int tile = static_cast<int>(blockIdx.x) % tiles_per_matrix;
  const int eigen_slot = tid / kGroupWidth;
  const int group_lane = tid & (kGroupWidth - 1);
  const int eigen_index = tile * kEigenpairsPerBlock + eigen_slot;
  const int64_t vector_offset = static_cast<int64_t>(matrix) * n;
  const int64_t matrix_offset = vector_offset * n;
  for (int index = tid; index < n; index += blockDim.x) {
    d[index] = input_diagonal[vector_offset + index];
    e[index] = input_off_diagonal[vector_offset + index];
  }
  __syncthreads();

  float local_low = FLT_MAX;
  float local_high = -FLT_MAX;
  for (int index = tid; index < n; index += blockDim.x) {
    const float radius = (index ? fabsf(e[index - 1]) : 0.0f) +
        (index + 1 < n ? fabsf(e[index]) : 0.0f);
    local_low = fminf(local_low, d[index] - radius);
    local_high = fmaxf(local_high, d[index] + radius);
  }
  lower_bounds[tid] = local_low;
  upper_bounds[tid] = local_high;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      lower_bounds[tid] = fminf(lower_bounds[tid], lower_bounds[tid + stride]);
      upper_bounds[tid] = fmaxf(upper_bounds[tid], upper_bounds[tid + stride]);
    }
    __syncthreads();
  }
  const float global_low = lower_bounds[0];
  const float global_high = upper_bounds[0];
  if (tid == 0 && tile == 0) {
    info[matrix] = 0;
  }

  if (eigen_slot < kEigenpairsPerBlock && eigen_index < n) {
    const unsigned int group_mask = __activemask();
    const float margin = 8.0f * FLT_EPSILON *
        (1.0f + fmaxf(fabsf(global_low), fabsf(global_high)));
    const float pivot_min = 1.0e-20f *
        (1.0f + global_high - global_low);
    if (group_lane == 0) {
      float low = global_low - margin;
      float high = global_high + margin;
      for (int iteration = 0; iteration < kBisectionIterations; ++iteration) {
        const float midpoint = 0.5f * (low + high);
        float pivot = d[0] - midpoint;
        if (fabsf(pivot) < pivot_min) {
          pivot = -pivot_min;
        }
        int count = pivot < 0.0f;
        for (int row = 1; row < n; ++row) {
          pivot = d[row] - midpoint - e[row - 1] * e[row - 1] / pivot;
          if (fabsf(pivot) < pivot_min) {
            pivot = -pivot_min;
          }
          count += pivot < 0.0f;
        }
        if (count <= eigen_index) {
          low = midpoint;
        } else {
          high = midpoint;
        }
      }
      const float eigenvalue = 0.5f * (low + high);
      lower_bounds[eigen_slot] = eigenvalue;
      values[vector_offset + eigen_index] = eigenvalue;
    }
    __syncwarp(group_mask);
    const float eigenvalue = lower_bounds[eigen_slot];

    float* factors = tile_factors + eigen_slot;
    float* eigenvector = tile_vectors + eigen_slot;
    if (group_lane == 0) {
      for (int row = 0; row < n; ++row) {
        const int pattern = (row * 17 + eigen_index * 13) % 23;
        eigenvector[row * kVectorPitch] =
            static_cast<float>(pattern - 11) / 11.0f;
      }
      const int inverse_iterations = n == 176 ? 3 : 2;
      for (int iteration = 0; iteration < inverse_iterations; ++iteration) {
        const float signed_shift = (iteration & 1) ? 1.0f : -1.0f;
