      (column > 0 &&
       fabsf(localized_values[value_offset + column] -
             localized_values[value_offset + column - 1]) <= threshold) ||
      (column + 1 < n &&
       fabsf(localized_values[value_offset + column + 1] -
             localized_values[value_offset + column]) <= threshold);
  if (!clustered) {
    return;
  }

  float rayleigh = 0.0f;
  for (int row = tid; row < n; row += blockDim.x) {
    const float value = vectors[matrix_offset + row * n + column];
    rayleigh += diagonal[value_offset + row] * value * value;
    if (row + 1 < n) {
      rayleigh += 2.0f * off_diagonal[value_offset + row] * value *
          vectors[matrix_offset + (row + 1) * n + column];
    }
  }
  reduction[tid] = rayleigh;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride; stride >>= 1) {
    if (tid < stride) {
      reduction[tid] += reduction[tid + stride];
    }
    __syncthreads();
  }
  if (tid == 0) {
    values[value_offset + column] = reduction[0];
  }
}

